mapper.select:
SELECT count(DISTINCT a.id) FROM ucloud.api_interface_alarm_data a LEFT JOIN system_docking.api_platform_index_info b ON a.index_code=b.index_code LEFT JOIN system_docking.api_interface_system_platform_info c ON b.platform_id=c.id RIGHT JOIN system_docking.api_system_resource_ip d ON a.resource_ip=d.ip_address LEFT JOIN system_docking.api_system_resource e ON d.resource_id=e.id WHERE b.is_enable='1' AND c.is_enable='1' AND d.is_enable='1'
AND b.id=#{params.indicators}
AND LEFT(a.lastOccurTime,10) ${params.times}

SELECT DISTINCT a.lastOccurTime AS alarm_time,b.index_name,c.platfrom_name,a.resource_ip, a.resource_name AS resource_desc,a.alarm_count AS alarm_value,a.description FROM ucloud.api_interface_alarm_data a LEFT JOIN system_docking.api_platform_index_info b ON a.index_code=b.index_code LEFT JOIN system_docking.api_interface_system_platform_info c ON b.platform_id=c.id RIGHT JOIN system_docking.api_system_resource_ip d ON a.resource_ip=d.ip_address LEFT JOIN system_docking.api_system_resource e ON d.resource_id=e.id WHERE b.is_enable='1' AND c.is_enable='1' AND d.is_enable='1'
AND b.id=#{params.indicators}
AND LEFT(a.lastOccurTime,10) ${params.times}
ORDER BY alarm_time
${params.limit}
